    int bit_clks = int'(prescale) * 8;
    // start bit
    rxd = 1'b0;
    wait_clks(bit_clks);
    // data bits (LSB first)
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(bit_clks);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(bit_clks);
  endtask

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
