  // -------------------------------------------------
  // Clock generation
  logic clk = 0;
  initial begin
    forever #(8) clk = ~clk;   // 125 MHz
  end

  // -------------------------------------------------
  // DUT signals
  logic        rst      = 0;
  logic        rxd      = 1;
  logic [15:0] prescale = 16'd5;   // preset value (non‑zero)

  logic        busy;
  logic        overrun_error;
  logic        frame_error;
  logic        m_axis_tvalid;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tready;

  // AXI‐stream sink is always ready
  assign m_axis_tready = 1'b1;

  // -------------------------------------------------
  // Instantiate the RX module (default DATA_WIDTH = 8)
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // -------------------------------------------------
  // Timing constants (prescale = 5 → 18 init cycles, 39 cycles per bit)
  localparam int PRESCALE_VAL = 5;
  localparam int INITIAL_WAIT = (PRESCALE_VAL << 2) - 2; // 18
  localparam int WAIT_BIT    = (PRESCALE_VAL << 3) - 1;  // 39
  localparam int TOTAL_CYCLES = INITIAL_WAIT + 8 * WAIT_BIT; // 330

  // -------------------------------------------------
  // Task: transmit a byte and finish when 0x5A is received
  task automatic send_frame_byte(input logic [7:0] data);
    // Wait until the DUT is idle
    wait (!busy);

    // Drive start bit (low for one cycle)
    rxd = 0;
    @(posedge clk);

    // Wait until the first data‑bit sampling instant
    repeat (INITIAL_WAIT) @(posedge clk);

    // Send 8 data bits, MSB‑first
    for (int i = 7; i >= 0; i--) begin
      if (i != 7) begin
        repeat (WAIT_BIT) @(posedge clk);
      end
      rxd = data[i];
    end

    // One more bit period before the stop bit
    repeat (WAIT_BIT) @(posedge clk);
    // Drive stop bit (high)
    rxd = 1;
    // Hold stop high for one bit period
    repeat (WAIT_BIT) @(posedge clk);

    // Wait for the generated AXI‑stream word
    wait (m_axis_tvalid && m_axis_tdata == 8'h5A);
    $finish;
  endtask

  // -------------------------------------------------
  // First initial block: cause a stop‑bit sample, assert reset at the
  // exact cycle when the stop bit is sampled, then release reset.
  initial begin
    // Start in reset
    #1;
    rst = 0;

    // Drive a start condition
    rxd = 0;               // start low
    @(posedge clk);        // DUT samples the start bit
    rxd = 1;               // release start

    // Wait until the receiver signals it is busy (frame start)
    wait (busy);

    // Wait the deterministic number of cycles until the stop‑bit sample
    repeat (TOTAL_CYCLES) @(posedge clk);

    // Assert reset on the exact cycle when a good stop bit is sampled
    rst <= 1;
    repeat (2) @(posedge clk);   // keep reset asserted briefly
    rst <= 0;                    // release reset
  end

  // -------------------------------------------------
  // Second initial block: after reset release, wait for idleness and send
  // a fresh frame that ends with 0x5A.  When that frame is accepted the
  // coverage point fires and we finish.
  initial begin
    // Wait for reset to be released and the DUT to become idle again
    wait (!rst);
    wait (!busy);

    // Transmit a new frame containing 0x5A
    send_frame_byte(8'h5A);
  end

endmodule
